"""QQ-字体切换的字体供给路由。

不内置大体积字体二进制：优先复用本机已安装的霞鹜文楷（如 ComfyUI_LayerStyle
自带的 LXGWWenKai-*.ttf），或本包 fonts/ 目录下的同名文件。找不到时返回 404，
前端 @font-face 加载失败会自然回退到下一字体，不影响核心功能。

路由（挂到 PromptServer，任何一步不可用都静默跳过）：
  GET /qq_fonts/available  -> {"wenkai": bool}
  GET /qq_fonts/wenkai     -> 霞鹜文楷 TTF（FileResponse）
"""

from pathlib import Path

_HERE = Path(__file__).resolve().parent              # .../QQ_ComfyUI_Tools/node_modules
_PACKAGE = _HERE.parent                              # .../QQ_ComfyUI_Tools
_CUSTOM_NODES = _PACKAGE.parent                      # .../custom_nodes

# 候选字体目录：本包 fonts/ 优先，其次 LayerStyle 自带字体目录。
_FONT_DIRS = [
    _PACKAGE / "fonts",
    _CUSTOM_NODES / "ComfyUI_LayerStyle" / "font",
]


def find_wenkai() -> Path | None:
    """返回第一个存在的霞鹜文楷 TTF；没有则 None。"""
    for directory in _FONT_DIRS:
        try:
            if not directory.is_dir():
                continue
            matches = sorted(directory.glob("LXGWWenKai*.ttf"))
            if matches:
                return matches[0]
        except OSError:
            continue
    return None


def register() -> None:
    """挂到 PromptServer；没有 aiohttp/server 时静默跳过。"""
    try:
        from aiohttp import web
        from server import PromptServer
    except Exception:
        return
    server = getattr(PromptServer, "instance", None)
    routes = getattr(server, "routes", None) if server is not None else None
    if routes is None or getattr(server, "_qq_font_routes", False):
        return

    @routes.get("/qq_fonts/available")
    async def available(request):
        return web.json_response({"wenkai": find_wenkai() is not None})

    @routes.get("/qq_fonts/wenkai")
    async def wenkai(request):
        target = find_wenkai()
        if target is None:
            return web.json_response({"error": "未找到霞鹜文楷字体"}, status=404)
        return web.FileResponse(
            target,
            headers={"Content-Type": "font/ttf", "Cache-Control": "max-age=86400"},
        )

    server._qq_font_routes = True
